    "aspect_ratio": "A1-portrait",
    "audience": "data-report",
    "tone": "data-forward, modern",
    "venue": null
  },
  "brief": {
    "title": "JS Framework Benchmark: 5 Years of Browser Performance Testing",
    "one_liner": "A comprehensive overview of the official JavaScript web framework benchmark spanning Chrome 55 through Chrome 146, tracking how the testing methodology and ecosystem have evolved.",
    "goal": "Viewers should understand the scale, longevity, and methodology of the JS Framework Benchmark, appreciate key milestones in its evolution, and recognize why cross-version comparisons require caution."
  },
  "sections": [
    {
      "id": "overview",
      "title": "What Is the JS Framework Benchmark?",
      "objective": "Introduce the benchmark's purpose: comparing JavaScript web frameworks on real-world DOM operations in Chrome, and explain why it matters to the developer community."
    },
    {
      "id": "timeline",
      "title": "Benchmark Timeline: Chrome 55 → Chrome 146",
      "objective": "Visualize the history of 60+ official benchmark runs across 8 years (2017–2026), highlighting platform coverage (OSX vs Windows) and keyed-only vs full runs."
    },
    {
      "id": "methodology",
      "title": "Methodology Milestones",
      "objective": "Highlight the key methodology changes — the switch to weighted geometric mean in Chrome 118, CPU throttling adjustments, and measurement fine-tuning — and why cross-version comparisons are unsafe."
    },
    {
      "id": "coverage",
      "title": "Platform & Framework Coverage at a Glance",
      "objective": "Show the breakdown of runs by year and platform, and note the alternating pattern of keyed-only vs full framework runs in recent versions."
    },
    {
      "id": "takeaways",
      "title": "Key Takeaways for Developers",
      "objective": "Summarize actionable insights: always compare within the same Chrome version, consult the latest run for current standings, and understand keyed vs non-keyed modes."
    }
  ],
  "metrics": [
    {
      "label": "Total Official Benchmark Runs",
      "value": "60+",
      "context": "From Chrome 55 (2017) to Chrome 146 (2026)"
    },
    {
      "label": "Chrome Versions Covered",
      "value": "55 – 146",
      "context": "Spanning approximately 8 years of browser releases"
    },
    {
      "label": "Scoring Method Change",
      "value": "Chrome 118",
      "context": "Switched to weighted geometric mean for overall result"
    },
    {
      "label": "Primary Platform",
      "value": "macOS (OSX)",
      "context": "Only 2 out of 60+ runs were on Windows (Chrome 104, 121)"
    },
    {
      "label": "Runs in 2025 Alone",
      "value": "12",
      "context": "Chrome 132 through Chrome 143, the most active single year"
    }
  ]
}

