[metadata] {"type": "create", "filePath": "/app/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>JS Framework Benchmark - Infographic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

  :root {
    --bg-deep: #070d1a;
    --bg-mid: #0c1629;
    --bg-card: #111d35;
    --bg-card-hover: #162544;
    --border: #1e3058;
    --border-bright: #2a4478;
    --text-primary: #e8edf5;
    --text-secondary: #8b9cc0;
    --text-muted: #5a6f99;
    --accent-blue: #3b82f6;
    --accent-blue-glow: #3b82f640;
    --accent-teal: #06b6d4;
    --accent-teal-glow: #06b6d440;
    --accent-amber: #f59e0b;
    --accent-amber-glow: #f59e0b40;
    --accent-red: #ef4444;
    --accent-green: #10b981;
    --accent-purple: #8b5cf6;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg-deep);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    width: 1200px;
    height: 1697px;
    overflow: hidden;
    position: relative;
  }

  /* Dot grid background */
  body::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle, #1e305820 1px, transparent 1px);
    background-size: 24px 24px;
    pointer-events: none;
    z-index: 0;
  }

  .poster {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    padding: 40px 48px;
    display: flex;
    flex-direction: column;
    gap: 28px;
  }

  /* === HEADER === */
  .header {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  .header-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
  }

  .header-title-block {
    flex: 1;
  }

  .header-label {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--accent-blue);
    margin-bottom: 8px;
  }

  .header-title {
    font-size: 36px;
    font-weight: 900;
    line-height: 1.1;
    color: var(--text-primary);
    letter-spacing: -0.5px;
  }

  .header-title span {
    color: var(--accent-teal);
  }

  .header-subtitle {
    font-size: 16px;
    font-weight: 400;
    color: var(--text-secondary);
    margin-top: 8px;
    line-height: 1.5;
  }

  .hero-stats {
    display: flex;
    gap: 16px;
    flex-shrink: 0;
  }

  .hero-stat {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px 24px;
    text-align: center;
    min-width: 140px;
    position: relative;
    overflow: hidden;
  }

  .hero-stat::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
  }

  .hero-stat.blue::before { background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal)); }
  .hero-stat.amber::before { background: linear-gradient(90deg, var(--accent-amber), #f97316); }
  .hero-stat.teal::before { background: linear-gradient(90deg, var(--accent-teal), var(--accent-green)); }

  .hero-stat-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 32px;
    font-weight: 700;
    line-height: 1;
  }

  .hero-stat.blue .hero-stat-value { color: var(--accent-blue); }
  .hero-stat.amber .hero-stat-value { color: var(--accent-amber); }
  .hero-stat.teal .hero-stat-value { color: var(--accent-teal); }

  .hero-stat-label {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--text-muted);
    margin-top: 6px;
  }

  .divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--border-bright), transparent);
  }

  /* === OVERVIEW BADGES === */
  .overview {
    display: flex;
    gap: 12px;
  }

  .badge {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 16px;
    flex: 1;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .badge-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 18px;
  }

  .badge-icon.blue { background: var(--accent-blue-glow); color: var(--accent-blue); }
  .badge-icon.teal { background: var(--accent-teal-glow); color: var(--accent-teal); }
  .badge-icon.amber { background: var(--accent-amber-glow); color: var(--accent-amber); }
  .badge-icon.green { background: #10b98130; color: var(--accent-green); }

  .badge-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .badge-label {
    font-size: 12px;
    font-weight: 700;
    color: var(--text-primary);
  }

  .badge-desc {
    font-size: 10px;
    color: var(--text-muted);
    line-height: 1.3;
  }

  /* === TIMELINE (CENTERPIECE) === */
  .timeline-section {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .section-header {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .section-header-line {
    flex: 1;
    height: 1px;
    background: var(--border);
  }

  .section-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--accent-teal);
    white-space: nowrap;
  }

  .timeline {
    position: relative;
    background: var(--bg-mid);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 24px 32px;
    flex: 1;
    display: grid;
    grid-template-columns: 100px 40px 1fr 200px;
    grid-template-rows: repeat(8, 1fr);
    gap: 0;
    align-items: center;
  }

  /* Timeline center line */
  .timeline::before {
    content: '';
    position: absolute;
    left: 150px;
    top: 40px;
    bottom: 40px;
    width: 3px;
    background: linear-gradient(180deg, var(--accent-blue), var(--accent-teal), var(--accent-amber), var(--accent-teal));
    border-radius: 2px;
  }

  .tl-year {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    color: var(--text-secondary);
    text-align: right;
    padding-right: 12px;
  }

  .tl-dot {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    position: relative;
    z-index: 2;
    justify-self: center;
  }

  .tl-dot.blue { background: var(--accent-blue); box-shadow: 0 0 12px var(--accent-blue-glow); }
  .tl-dot.teal { background: var(--accent-teal); box-shadow: 0 0 12px var(--accent-teal-glow); }
  .tl-dot.amber { background: var(--accent-amber); box-shadow: 0 0 16px var(--accent-amber-glow); }
  .tl-dot.green { background: var(--accent-green); box-shadow: 0 0 12px #10b98140; }

  .tl-info {
    padding-left: 20px;
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .tl-chrome {
    font-family: 'JetBrains Mono', monospace;
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
  }

  .tl-detail {
    font-size: 11px;
    color: var(--text-muted);
  }

  .tl-badge {
    justify-self: end;
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 6px;
    background: var(--bg-card);
    border: 1px solid var(--border);
  }

  .tl-badge.runs { color: var(--accent-blue); border-color: #3b82f630; }
  .tl-badge.macos { color: var(--accent-teal); border-color: #06b6d430; }
  .tl-badge.windows { color: var(--accent-amber); border-color: #f59e0b30; }
  .tl-badge.method { color: var(--accent-amber); border-color: #f59e0b30; background: #f59e0b10; }
  .tl-badge.keyed { color: var(--accent-purple); border-color: #8b5cf630; }

  /* Chrome 118 callout */
  .methodology-callout {
    background: linear-gradient(135deg, #f59e0b08, #f59e0b15);
    border: 1px solid #f59e0b40;
    border-radius: 12px;
    padding: 18px 24px;
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }

  .callout-icon {
    font-size: 28px;
    flex-shrink: 0;
    line-height: 1;
  }

  .callout-content {
    flex: 1;
  }

  .callout-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--accent-amber);
    margin-bottom: 6px;
    font-family: 'JetBrains Mono', monospace;
  }

  .callout-text {
    font-size: 12px;
    color: var(--text-secondary);
    line-height: 1.6;
  }

  .callout-text strong {
    color: var(--text-primary);
  }

  /* === BOTTOM ROW: CHARTS + METHODOLOGY === */
  .bottom-row {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
    height: 280px;
  }

  .chart-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 20px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .chart-card-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--accent-blue);
    margin-bottom: 4px;
  }

  .chart-card-desc {
    font-size: 10px;
    color: var(--text-muted);
    margin-bottom: 12px;
  }

  .chart-container {
    flex: 1;
    position: relative;
    overflow: hidden;
  }

  .chart-container canvas, .chart-container svg {
    width: 100% !important;
    height: 100% !important;
  }

  /* === BAR CHART (custom SVG) === */
  .bar-chart {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    height: 100%;
    padding-bottom: 24px;
    position: relative;
  }

  .bar-chart::after {
    content: '';
    position: absolute;
    bottom: 24px;
    left: 0;
    right: 0;
    height: 1px;
    background: var(--border);
  }

  .bar-col {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    height: 100%;
    justify-content: flex-end;
    position: relative;
  }

  .bar-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    color: var(--text-secondary);
  }

  .bar {
    width: 100%;
    border-radius: 4px 4px 0 0;
    min-height: 4px;
  }

  .bar.blue { background: linear-gradient(180deg, var(--accent-blue), #3b82f680); }
  .bar.teal { background: linear-gradient(180deg, var(--accent-teal), #06b6d480); }
  .bar.amber { background: linear-gradient(180deg, var(--accent-amber), #f59e0b80); }

  .bar-label {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    color: var(--text-muted);
    margin-top: 4px;
  }

  /* === DONUT CHART === */
  .donut-container {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    position: relative;
  }

  .donut-center-text {
    position: absolute;
    text-align: center;
  }

  .donut-center-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 28px;
    font-weight: 700;
    color: var(--accent-teal);
  }

  .donut-center-label {
    font-size: 10px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .platform-legend {
    display: flex;
    gap: 16px;
    justify-content: center;
    margin-top: 8px;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    color: var(--text-secondary);
  }

  .legend-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
  }

  /* === METHODOLOGY COMPARISON === */
  .method-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 20px;
    display: flex;
    flex-direction: column;
  }

  .method-grid {
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
  }

  .method-row {
    display: flex;
    gap: 8px;
  }

  .method-side {
    flex: 1;
    border-radius: 8px;
    padding: 10px 12px;
  }

  .method-side.before {
    background: #f59e0b10;
    border: 1px solid #f59e0b30;
  }

  .method-side.after {
    background: #06b6d410;
    border: 1px solid #06b6d430;
  }

  .method-side-label {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 4px;
  }

  .method-side.before .method-side-label { color: var(--accent-amber); }
  .method-side.after .method-side-label { color: var(--accent-teal); }

  .method-side-value {
    font-size: 12px;
    font-weight: 600;
    color: var(--text-primary);
    line-height: 1.4;
  }

  /* === KEY TAKEAWAYS === */
  .takeaways {
    display: flex;
    gap: 12px;
  }

  .takeaway {
    flex: 1;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 16px;
    display: flex;
    gap: 10px;
    align-items: flex-start;
  }

  .takeaway-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 20px;
    font-weight: 800;
    line-height: 1;
    flex-shrink: 0;
  }

  .takeaway:nth-child(1) .takeaway-num { color: var(--accent-blue); }
  .takeaway:nth-child(2) .takeaway-num { color: var(--accent-teal); }
  .takeaway:nth-child(3) .takeaway-num { color: var(--accent-green); }
  .takeaway:nth-child(4) .takeaway-num { color: var(--accent-amber); }
  .takeaway:nth-child(5) .takeaway-num { color: var(--accent-purple); }

  .takeaway-text {
    font-size: 11px;
    color: var(--text-secondary);
    line-height: 1.5;
  }

  .takeaway-text strong {
    color: var(--text-primary);
  }

  /* === FOOTER === */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 4px;
  }

  .footer-text {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    color: var(--text-muted);
    letter-spacing: 0.5px;
  }

  .footer-warning {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    color: var(--accent-amber);
    font-style: italic;
  }
</style>
</head>
<body>
<div class="poster">
  <!-- HEADER -->
  <div class="header">
    <div class="header-top">
      <div class="header-title-block">
        <div class="header-label">// Long-Running Performance Tracker</div>
        <div class="header-title">JS Framework <span>Benchmark</span></div>
        <div class="header-subtitle">A comprehensive overview of the official JavaScript web framework benchmark spanning Chrome 55 through Chrome 146 — tracking how the testing methodology and ecosystem have evolved across 8 years.</div>
      </div>
      <div class="hero-stats">
        <div class="hero-stat blue">
          <div class="hero-stat-value">60+</div>
          <div class="hero-stat-label">Official Runs</div>
        </div>
        <div class="hero-stat amber">
          <div class="hero-stat-value">55→146</div>
          <div class="hero-stat-label">Chrome Versions</div>
        </div>
        <div class="hero-stat teal">
          <div class="hero-stat-value">8 yrs</div>
          <div class="hero-stat-label">Of Data</div>
        </div>
      </div>
    </div>
    <div class="divider"></div>
  </div>

  <!-- OVERVIEW BADGES -->
  <div class="overview">
