const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-gpu']
  });

  const page = await browser.newPage();

  // Set viewport to A1 proportions at high resolution
  await page.setViewport({
    width: 1200,
    height: 1697,
    deviceScaleFactor: 2
  });

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and rendering to complete
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 1000));

  await page.screenshot({
    path: path.resolve(__dirname, 'output/final_poster.png'),
    type: 'png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 1200, height: 1697 }
  });

  console.log('Poster rendered to /app/output/final_poster.png');
  await browser.close();
})();

