<html lang="en">
<head>
<meta charset="utf-8">
<title>JS Framework Benchmark - Infographic Poster</title>
<style>
  :root {
    --bg-deep: #070d1a;
    --bg-mid: #0c1629;
    --bg-card: #111d35;
    --border: #1e3058;
    --border-bright: #2a4478;
    --text-primary: #e8edf5;
    --text-secondary: #8b9cc0;
    --text-muted: #5a6f99;
    --accent-blue: #3b82f6;
    --accent-blue-glow: #3b82f640;
    --accent-teal: #06b6d4;
    --accent-teal-glow: #06b6d440;
    --accent-amber: #f59e0b;
    --accent-amber-glow: #f59e0b40;
    --accent-green: #10b981;
    --accent-purple: #8b5cf6;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg-deep);
    color: var(--text-primary);
    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    width: 1200px;
    height: 1697px;
    overflow: hidden;
    position: relative;
  }

  body::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle, #1e305822 1px, transparent 1px);
    background-size: 24px 24px;
    pointer-events: none;
    z-index: 0;
  }

  .poster {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    padding: 36px 44px 30px;
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  .header { display: flex; flex-direction: column; gap: 14px; }
  .header-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 24px; }
  .header-title-block { flex: 1; }

  .header-label {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 10px; font-weight: 600; letter-spacing: 3px;
    text-transform: uppercase; color: var(--accent-blue); margin-bottom: 6px;
  }

  .header-title { font-size: 38px; font-weight: 900; line-height: 1.1; color: var(--text-primary); letter-spacing: -0.5px; }
  .header-title span { color: var(--accent-teal); }

  .header-subtitle {
    font-size: 13.5px; font-weight: 400; color: var(--text-secondary);
    margin-top: 8px; line-height: 1.55; max-width: 620px;
  }

  .hero-stats { display: flex; gap: 14px; flex-shrink: 0; }

  .hero-stat {
    background: var(--bg-card); border: 1px solid var(--border);
    border-radius: 12px; padding: 14px 22px; text-align: center;
    min-width: 135px; position: relative; overflow: hidden;
  }
  .hero-stat::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; }
  .hero-stat.blue::before { background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal)); }
  .hero-stat.amber::before { background: linear-gradient(90deg, var(--accent-amber), #f97316); }
  .hero-stat.teal::before { background: linear-gradient(90deg, var(--accent-teal), var(--accent-green)); }

  .hero-stat-value {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 30px; font-weight: 700; line-height: 1;
  }
  .hero-stat.blue .hero-stat-value { color: var(--accent-blue); }
  .hero-stat.amber .hero-stat-value { color: var(--accent-amber); }
  .hero-stat.teal .hero-stat-value { color: var(--accent-teal); }

  .hero-stat-label {
    font-size: 10px; font-weight: 600; text-transform: uppercase;
    letter-spacing: 1.5px; color: var(--text-muted); margin-top: 5px;
  }

  .divider { height: 1px; background: linear-gradient(90deg, transparent, var(--border-bright), transparent); }

  /* OVERVIEW BADGES */
  .overview { display: flex; gap: 12px; }
  .badge {
    background: var(--bg-card); border: 1px solid var(--border);
    border-radius: 10px; padding: 12px 14px; flex: 1;
    display: flex; align-items: center; gap: 10px;
  }
  .badge-icon {
    width: 34px; height: 34px; border-radius: 8px;
    display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  }
  .badge-icon.blue { background: var(--accent-blue-glow); }
  .badge-icon.teal { background: var(--accent-teal-glow); }
  .badge-icon.amber { background: var(--accent-amber-glow); }
  .badge-icon.green { background: #10b98130; }
  .badge-text { display: flex; flex-direction: column; gap: 2px; }
  .badge-label { font-size: 12px; font-weight: 700; color: var(--text-primary); }
  .badge-desc { font-size: 10px; color: var(--text-muted); line-height: 1.3; }

  /* SECTION HEADERS */
  .section-header { display: flex; align-items: center; gap: 10px; }
  .section-header-line { flex: 1; height: 1px; background: var(--border); }
  .section-title {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 12px; font-weight: 700; letter-spacing: 2px;
    text-transform: uppercase; color: var(--accent-teal); white-space: nowrap;
  }

  /* TIMELINE */
  .timeline-section { flex: 1; display: flex; flex-direction: column; gap: 10px; }

  .timeline {
    position: relative; background: var(--bg-mid); border: 1px solid var(--border);
    border-radius: 14px; padding: 20px 28px; flex: 1;
    display: grid; grid-template-columns: 90px 36px 1fr 190px;
    grid-template-rows: repeat(8, 1fr); gap: 0; align-items: center;
  }

  .timeline::before {
    content: ''; position: absolute; left: 136px; top: 36px; bottom: 36px;
    width: 3px; border-radius: 2px;
    background: linear-gradient(180deg, var(--accent-blue), var(--accent-teal) 30%, var(--accent-amber) 55%, var(--accent-teal) 75%, var(--accent-blue));
  }

  .tl-year {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 12px; font-weight: 700; color: var(--text-secondary);
    text-align: right; padding-right: 10px;
  }
  .tl-dot {
    width: 14px; height: 14px; border-radius: 50%;
    position: relative; z-index: 2; justify-self: center;
  }
  .tl-dot.blue { background: var(--accent-blue); box-shadow: 0 0 10px var(--accent-blue-glow); }
  .tl-dot.teal { background: var(--accent-teal); box-shadow: 0 0 10px var(--accent-teal-glow); }
  .tl-dot.amber { background: var(--accent-amber); box-shadow: 0 0 14px var(--accent-amber-glow); width: 18px; height: 18px; }
  .tl-dot.green { background: var(--accent-green); box-shadow: 0 0 10px #10b98140; }

  .tl-info { padding-left: 16px; display: flex; flex-direction: column; gap: 1px; }
  .tl-chrome {
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 13px; font-weight: 600; color: var(--text-primary);
  }
  .tl-detail { font-size: 10px; color: var(--text-muted); }

  .tl-badge {
    justify-self: end;
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 10px; font-weight: 600; padding: 3px 8px; border-radius: 5px;
    background: var(--bg-card); border: 1px solid var(--border); white-space: nowrap;
